import { test, expect } from "../helpers/theme-browser";

const themes = [
  ["Lavender", "purple", "light"],
  ["Nightbloom", "purple", "dark"],
  ["Chalk", "vercel", "light"],
  ["Obsidian", "vercel", "dark"],
] as const;

for (const [name, appearance, mode] of themes) {
  test(`support pages: ${name}`, async ({ page }, info) => {
    await page.setViewportSize({
      width: info.project.name === "mobile" ? 390 : 1440,
      height: 1000,
    });
    await page.emulateMedia({ reducedMotion: "reduce" });
    await page.addInitScript(
      ({ appearance, mode }) => {
        localStorage.setItem("mailloop-appearance", appearance);
        localStorage.setItem("mailloop-theme", mode);
      },
      { appearance, mode },
    );
    for (const [route, title] of [
      ["/help", "Help center"],
      ["/contact", "Contact us"],
    ]) {
      await page.goto(route);
      await expect(page.locator("html")).toHaveAttribute(
        "data-appearance",
        appearance,
      );
      await expect(page.locator("html")).toHaveAttribute("data-theme", mode);
      await expect(
        page.getByRole("heading", { level: 1, name: title }),
      ).toBeVisible();
      await page.evaluate(() => document.fonts.ready);
      const metrics = await page.locator("main").evaluate((main) => {
        const pixel = document.createElement("canvas");
        pixel.width = pixel.height = 1;
        const context = pixel.getContext("2d", { willReadFrequently: true })!;
        const luminance = (color: string) => {
          // color-mix can resolve to color(srgb ...), as well as rgb(...).
          context.clearRect(0, 0, 1, 1);
          context.fillStyle = color;
          context.fillRect(0, 0, 1, 1);
          const c = Array.from(context.getImageData(0, 0, 1, 1).data)
            .slice(0, 3)
            .map((v) => {
              const n = v / 255;
              return n <= 0.04045 ? n / 12.92 : ((n + 0.055) / 1.055) ** 2.4;
            });
          return c[0] * 0.2126 + c[1] * 0.7152 + c[2] * 0.0722;
        };
        const background = luminance(
          getComputedStyle(document.body).backgroundColor,
        );
        const contrast = Array.from(
          main.querySelectorAll(
            "p, h1, h2, h3, li, code, nav a, section a, p a",
          ),
        ).map((element) => {
          const foreground = luminance(getComputedStyle(element).color);
          return {
            text: element.textContent?.slice(0, 60),
            ratio:
              (Math.max(foreground, background) + 0.05) /
              (Math.min(foreground, background) + 0.05),
          };
        });
        return {
          contrast,
          overflow: document.documentElement.scrollWidth > innerWidth,
        };
      });
      expect(metrics.overflow).toBe(false);
      for (const { text, ratio } of metrics.contrast)
        expect(ratio, `${name}: ${text}`).toBeGreaterThanOrEqual(4.5);
      await info.attach(`${name}-${route.slice(1)}`, {
        body: await page.screenshot({
          fullPage: true,
          path: info.outputPath(`${name}-${route.slice(1)}.png`),
          style: "nextjs-portal { display:none }",
        }),
        contentType: "image/png",
      });
    }
  });
}
